(function(window){

function Typed(element,options){

this.element=document.querySelector(element);

this.strings=options.strings || [];

this.typeSpeed=options.typeSpeed || 100;

this.backSpeed=options.backSpeed || 50;

this.backDelay=options.backDelay || 1000;

this.loop=options.loop || false;


this.index=0;

this.charIndex=0;

this.isDeleting=false;


this.start();

}



Typed.prototype.start=function(){

let current=this.strings[this.index];


if(!this.isDeleting){

this.element.textContent=
current.substring(0,this.charIndex++);


if(this.charIndex>current.length){

setTimeout(()=>{

this.isDeleting=true;

this.start();

},this.backDelay);


return;

}


}

else{


this.element.textContent=
current.substring(0,this.charIndex--);



if(this.charIndex<0){

this.isDeleting=false;

this.index++;


if(this.index>=this.strings.length){

this.index=0;

}


}


}



setTimeout(()=>this.start(),

this.isDeleting?
this.backSpeed:
this.typeSpeed);


};



window.Typed=Typed;


})(window);
